"which branch am I on?" -> {"probes":[{"probe":"status"}]}
"what is staged?" -> {"probes":[{"probe":"diff","staged":true}]}
"what changed in src/app.js?" -> {"probes":[{"probe":"diff","path":"src/app.js"}]}
